@prefix cdif: <https://w3id.org/cdif/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/var/temperature> ;
            sh:resultMessage "For data description level, a cdi:InstanceVariable should specify cdif:physicalDataType." ;
            sh:resultPath cdif:physicalDataType ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "For data description level, a cdi:InstanceVariable should specify cdif:physicalDataType." ;
                    sh:minCount 1 ;
                    sh:or ( [ sh:nodeKind sh:IRI ] [ sh:datatype xsd:string ;
                                sh:minLength 3 ] [ sh:class schema1:DefinedTerm ] ) ;
                    sh:path cdif:physicalDataType ;
                    sh:severity sh:Warning ] ] .

@prefix cdif: <https://w3id.org/cdif/> .
@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/var/temperature> ;
            sh:resultMessage "a variableMeasured should have a text description explaining the variable" ;
            sh:resultPath schema1:description ;
            sh:resultSeverity sh:Info ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:message "a variableMeasured should have a text description explaining the variable" ;
                    sh:minCount 1 ;
                    sh:minLength 10 ;
                    sh:path schema1:description ;
                    sh:severity sh:Info ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/var/temperature> ;
            sh:resultMessage "a variable should carry a schema:propertyID identifying the concept it measures." ;
            sh:resultPath schema1:propertyID ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "a variable should carry a schema:propertyID identifying the concept it measures." ;
                    sh:minCount 1 ;
                    sh:path schema1:propertyID ;
                    sh:severity sh:Warning ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/var/temperature> ;
            sh:resultMessage "for cdi InstanceVariable a physical data type should be provided." ;
            sh:resultPath cdif:physicalDataType ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "for cdi InstanceVariable a physical data type should be provided." ;
                    sh:minCount 1 ;
                    sh:path cdif:physicalDataType ;
                    sh:severity sh:Warning ] ] .

